from dataclasses import dataclass
from typing import Any

@dataclass
class Entity:
    """Base class for all entities — equality is identity-based."""
    id: str

    def __eq__(self, other: Any) -> bool:
        if not isinstance(other, self.__class__):
            return False
        return self.id == other.id

    def __hash__(self) -> int:
        return hash(self.id)


class Customer(Entity):
    def __init__(self, id: str, name: str, email: str):
        super().__init__(id)
        self.name = name
        self.email = email


# Equality by ID, not by attributes:
customer_v1 = Customer(id="C-001", name="Alice", email="old@example.com")
customer_v2 = Customer(id="C-001", name="Alice", email="new@example.com")
assert customer_v1 == customer_v2   # True — same entity, different state snapshot

different_customer = Customer(id="C-002", name="Alice", email="old@example.com")
assert customer_v1 != different_customer  # False — different identity

class Subscription:
    def __init__(self, id: str, customer_id: str, plan: str):
        self.id = id                    # stable identity — never changes
        self.customer_id = customer_id  # stable reference
        self.plan = plan                # mutable state
        self.status = "ACTIVE"          # mutable state
        self.billing_cycle = "MONTHLY"  # mutable state
        self._events = []

    def upgrade(self, new_plan: str) -> None:
        """State changes; identity stays."""
        old_plan = self.plan
        self.plan = new_plan
        self._events.append(
            PlanUpgraded(subscription_id=self.id, from_plan=old_plan, to_plan=new_plan)
        )

    def cancel(self) -> None:
        if self.status == "CANCELLED":
            raise ValueError("Already cancelled")
        self.status = "CANCELLED"
        self._events.append(SubscriptionCancelled(subscription_id=self.id))

    def reactivate(self, plan: str) -> None:
        if self.status != "CANCELLED":
            raise ValueError("Can only reactivate a cancelled subscription")
        self.status = "ACTIVE"
        self.plan = plan
        # Same identity — this is a continuation of the same subscription's history

class Invoice:
    def __init__(self, id: str, customer_id: str, amount: "Money"):
        self.id = id
        self.customer_id = customer_id
        self.amount = amount
        self.status = "DRAFT"
        self.paid_at = None

    # BAD: raw mutation, no invariant protection
    # self.status = "PAID"  # anyone can do this anywhere in the codebase

    def issue(self) -> None:
        """DRAFT -> ISSUED. Validate preconditions first."""
        if self.status != "DRAFT":
            raise InvalidStateTransition(
                f"Cannot issue an invoice in status {self.status}"
            )
        if self.amount.is_zero():
            raise ValueError("Cannot issue a zero-amount invoice")
        self.status = "ISSUED"

    def mark_paid(self, paid_at: datetime) -> None:
        """ISSUED -> PAID. Only valid for issued invoices."""
        if self.status != "ISSUED":
            raise InvalidStateTransition(
                f"Cannot mark as paid; current status is {self.status}"
            )
        self.status = "PAID"
        self.paid_at = paid_at

    def void(self, reason: str) -> None:
        """DRAFT or ISSUED -> VOID. Cannot void a paid invoice."""
        if self.status == "PAID":
            raise InvalidStateTransition("Cannot void a paid invoice; issue a credit note")
        self.status = "VOID"

class BankAccount:
    # Internal: used only by the repository for reconstitution
    def __init__(self, id: str, customer_id: str, balance: "Money"):
        self.id = id
        self.customer_id = customer_id
        self.balance = balance
        self.status = "OPEN"

    @classmethod
    def open(cls, customer_id: str, opening_balance: "Money") -> "BankAccount":
        """Factory method for NEW accounts — enforces creation invariants."""
        if opening_balance.amount < 10:
            raise ValueError("Opening balance must be at least $10")
        account = cls(
            id=generate_ulid(),
            customer_id=customer_id,
            balance=opening_balance
        )
        account._events.append(AccountOpened(account_id=account.id, ...))
        return account

    # Repository calls __init__ directly with persisted data — no validation needed

from dataclasses import dataclass, field
from datetime import datetime
from typing import List

@dataclass
class DomainEvent:
    occurred_at: datetime = field(default_factory=datetime.utcnow)

@dataclass
class OrderPlaced(DomainEvent):
    order_id: str = ""
    customer_id: str = ""

@dataclass
class OrderShipped(DomainEvent):
    order_id: str = ""
    tracking_number: str = ""


class Order:
    def __init__(self, id: str, customer_id: str):
        self.id = id
        self.customer_id = customer_id
        self.status = "PLACED"
        self._domain_events: List[DomainEvent] = [
            OrderPlaced(order_id=id, customer_id=customer_id)
        ]

    def ship(self, tracking_number: str) -> None:
        if self.status != "PLACED":
            raise InvalidStateTransition(f"Cannot ship order with status {self.status}")
        self.status = "SHIPPED"
        self._domain_events.append(
            OrderShipped(order_id=self.id, tracking_number=tracking_number)
        )

    def pull_events(self) -> List[DomainEvent]:
        """Called by application layer after save to dispatch events."""
        events, self._domain_events = self._domain_events, []
        return events
